"""
    Args:
        desired_wpm (int): the target words-per-minute value
                           you wish to achieve
        words_per_line (int): how many words per line your
                              test book contains on average
    Returns:
        seconds
    """
def time_per_line(desired_wpm: Any, words_per_line: Any) -> object {
    minute_fraction = words_per_line / (3 * desired_wpm);
    return (minute_fraction * 60);
}

"""
        Return the minimum number of character deletions,
        insertions and/or substitutions between two strings.
        :param str1: first string
        :param str2: second string
        :type str1: string
        :type str2: string
        :returns: levenshtein distance between the two strings
        :rtype: int
    """
def levenshtein_distance(str1: Any, str2: Any) -> object {
    (cols, rows) = (len(str1), len(str2));
    matrix = [[0 for col in range((cols + 1))] for row in range((rows + 1))];
    for col in range(1, (cols + 1)) {
        matrix[0][col] = col;
    }
    for row in range(1, (rows + 1)) {
        matrix[row][0] = row;
    }
    for row in range(1, (rows + 1)) {
        for col in range(1, (cols + 1)) {
            cost = 0 if (str1[(col - 1)] == str2[(row - 1)]) else 1;
            matrix[row][col] = min(
                (matrix[row][(col - 1)] + 1),
                (matrix[(row - 1)][col] + 1),
                (matrix[(row - 1)][(col - 1)] + cost)
            );
        }
    }
    return matrix[rows][cols];
}

"""
    Returns True if string 's' is integer and False if not.
    's' MUST be a string.

    :param s: string with number
    :type s: str
    :rtype: bool
    """
def is_int(s: Any) -> object {
    try {
        int(s);
        return True;
    } except ValueError {
        return False;
    }
